faqs=[('这里是 OpenAI 官方网站吗？','不是。AI Plus 是独立的 AI 订阅信息与购买导航站，与 OpenAI、Anthropic、xAI 无隶属关系。购买入口指向第三方服务商，订阅权益以相应产品官方页面为准。'),('可以用微信或支付宝购买吗？','参考服务商提供微信、支付宝购买渠道。本页的购买按钮会前往小店，具体付款方式、库存与成交价格以下单页面为准。'),('ChatGPT Plus、Pro 和 Codex 怎么选？','日常写作、学习和轻量编程可以先了解 Plus；高频编程与研究再评估 Pro。Codex 的访问方式和可用额度取决于官方当前套餐规则，请在购买前确认，避免把网页套餐和 API 用量混为一谈。'),('Claude Pro 和 Max 怎么选？','先根据使用频率评估 Pro；如果持续触及用量限制，再比较 Max 档位。实际可用量会受模型、任务长度和官方规则影响，并不代表无限使用。'),('网站上的价格就是最终价格吗？','这里展示的是 2026 年 9 月 13 日参考服务商的页面报价，并非官方定价或锁价承诺。套餐名称、价格、库存和实际权益，请在付款前向服务商确认。'),('需要在这个网站提交密码或账号信息吗？','不需要。本网站不接收密码、验证码、会话令牌或充值信息。会话令牌同样可能具有账号访问权限，请勿把它当作普通账号编号随意分享。具体交付方式请在购买前与服务商确认。'),('充值需要多久，售后找谁？','交付时间取决于套餐、库存和账号状态，以服务商确认结果为准。请保存订单号与沟通记录；到账、退款和售后问题由实际收款与交付的服务商处理。'),('现有订阅还没到期，可以续费或升级吗？','请先确认账号当前套餐、剩余时长和订阅渠道，再向服务商核对续费或升级规则。不要默认不同渠道会自动叠加，也不要在未确认时重复下单。')]
guides=[('choose-chatgpt','ChatGPT Plus / Pro 怎么选？','CHATGPT','从日常使用到高频 Codex，按工作强度选择适合自己的套餐。',[('先看你每天用 AI 做什么','如果主要是写邮件、改文章、读资料和轻量编程，可以先了解 Plus。选择套餐的起点应是日常任务，而不是看到更高档位就直接升级。'),('什么时候再考虑 Pro','当编码、研究或复杂文档成为每天的高频任务，并且现有用量经常限制工作，再比较 Pro 档位。记录自己遇到限制的频率，比只看套餐名称更有帮助。'),('Codex 与 API 用量需要分开确认','购买前核对官方当前提供的 Codex 访问方式、限制和额度。不要假定 ChatGPT 订阅自动包含 API 余额，也不要把商家标注的档位理解为所有场景下固定倍数的使用量。'),('付款前确认三件事','确认当前账号是否已有订阅、升级后剩余时长如何处理，以及最终套餐名称与成交价。本站页面报价供比较，下单以服务商实时确认为准。')]),('choose-claude','Claude Pro / Max 怎么选？','CLAUDE','看写作、长文档和 Claude Code 的使用节奏，再决定是否升级。',[('从你的真实使用频率出发','偶尔写作、读报告和辅助编程，先了解 Pro 的具体权益。如果每天长时间使用 Claude Code，再评估更高用量的 Max。'),('先区分偶尔限流与持续不足','偶尔遇到限制，不一定需要升级。观察工作中断是否频繁、是否影响交付，以及更换任务安排能否解决，再决定是否增加预算。'),('不要把更高用量理解为无限','用量会受任务长度、上下文、模型和官方规则影响。购买前查看最新官方说明，向服务商确认所售档位及账户适用条件。'),('保留购买与售后记录','下单前确认当前订阅状态、交付步骤、退款条件。开通后在自己的账号中查看套餐与到期时间，并保留订单记录。')]),('buying-guide','订阅前，先看这份购买指南','GUIDE','支付渠道、账号状态、到账与售后，一次梳理清楚。',[('选择适合自己的购买渠道','具备官方支持的支付条件时，可以查看官方订阅渠道。使用第三方服务时，先了解服务商身份、真实成交价、交付方式与售后约定。'),('确认账号状态与套餐','检查账号能否正常登录，是否有未到期订阅，以及当前订阅来自哪个渠道。先确认自己需要的产品和档位，再进行付款。'),('认真核对交付所需信息','本网站不收集账号凭据。不要在不明页面提交密码、验证码或会话令牌。会话令牌可能提供账号访问权限，即使不提供密码也不代表没有风险。'),('付款后检查到账结果','按实际订单说明完成后，在对应官方产品中检查套餐与有效期。有异常先联系实际服务商并提供订单号，不要连续重复付款。')])]
